{{ config(materialized='table', schema='POLITICS') }}

-- Source: Congress -- Committee Membership, 113th to 119th (26,971 rows)
-- Originally generated by gen_mart_models.py; hand-edited 2026-09-06 when the
-- loader went from a current-only snapshot to one snapshot per congress.
--
-- GRAIN: one row per (congress, committee_code, bioguide).
--
-- TWO THINGS TO KNOW BEFORE USING THIS:
--
--   party is NOT a party. It holds 'majority' and 'minority' on every row, in
--   every congress. Join POLITICS__FED_CONGRESS_LEGISLATORS for D/R.
--
--   snapshot_date is the day the roster was read, not a term. A member who
--   joined and left inside one congress shows only as of that day. Say "on the
--   committee as of the end of the 117th", never "was on it in 2021".
--
-- The dedupe below is one row: Fred Keller, K000395, appears twice on House
-- Education and Labor in the 116th at rank 20 and rank 22. That is an error in
-- the upstream YAML, not here. Lowest rank wins so the grain test stays honest.

with source as (
    select * from {{ source('ripple_raw', 'FED_CONGRESS_COMMITTEE_MEMBERSHIP') }}
),

ranked as (
    select
        CONGRESS as congress,
        SNAPSHOT_DATE as snapshot_date,
        SNAPSHOT_SHA as snapshot_sha,
        COMMITTEE_CODE as committee_code,
        COMMITTEE_NAME as committee_name,
        IS_SUBCOMMITTEE as is_subcommittee,
        BIOGUIDE as bioguide,
        MEMBER_NAME as member_name,
        PARTY as party,
        "RANK" as rank,
        TITLE as title,
        row_number() over (
            partition by CONGRESS, COMMITTEE_CODE, BIOGUIDE
            order by {{ ripple_num('"RANK"') }} asc nulls last
        ) as _dupe_rn
    from source
)

select
    congress,
    snapshot_date,
    snapshot_sha,
    committee_code,
    committee_name,
    is_subcommittee,
    bioguide,
    member_name,
    party,
    rank,
    title
from ranked
where _dupe_rn = 1
